--region helper
function UIActivityNightCatBossMainDialog:RefreshRewards()
    ---@type NightCatBossRankDojo
    local dojo = self._nightCatBossComponent:GetRankDojo()
    local myRank = checkNumber(dojo.playerRank.ranking)
    local itemTrans = self.CommonGoodsListLight.transform.parent:Find("TitleItem")
    if myRank <= 0 then
        ---未打过
        CfUtils.SetActive(itemTrans, false)
        CfUtils.SetActive(self.CommonGoodsListLight, false)
    else
        local rewards = ActivityNightCatBossMgr:GetRewardsByRankNum(myRank)
        if #rewards > 0 then
            CfUtils.SetActive(itemTrans, true)
            CfUtils.SetActive(self.CommonGoodsListLight, true)
            ---@type CommonGoodsListLight
            local scr = CfUtils.GetLuaScr(self.CommonGoodsListLight, "Game.Behaviours.CommonGoodsListLight")
            scr:FreshBaseUI(rewards)
        else
            CfUtils.SetActive(itemTrans, false)
            CfUtils.SetActive(self.CommonGoodsListLight, false)
        end
    end
end

function UIActivityNightCatBossMainDialog:RefreshRankInfo()
    ---@type NightCatBossRankingDialog
    local scr = CfUtils.GetLuaScr(self.RankingsDialog, "Game.Activity.NightCat.Boss.NightCatBossRankingDialog")
    scr:Refresh(self.activityId)
end
--endregion helper

return UIActivityNightCatBossMainDialog